WITH filtered_store_sales AS (SELECT * FROM store_sales WHERE sale_date BETWEEN '2023-08-01' AND '2024-10-08'), revenue_bucket_summary AS (SELECT CASE WHEN revenue >= 3400 THEN 'high' WHEN revenue >= 700 THEN 'mid' ELSE 'low' END AS revenue_bucket, ROUND(AVG(revenue), 2) AS avg_revenue, MIN(sale_date) AS first_sale_date FROM filtered_store_sales GROUP BY CASE WHEN revenue >= 3400 THEN 'high' WHEN revenue >= 700 THEN 'mid' ELSE 'low' END) SELECT * FROM revenue_bucket_summary WHERE avg_revenue < 77
